var report="Tools/DamageNumbers/BatchMeasurement.txt";System.IO.File.WriteAllText(report,"Damage number editor render measurement\n");int stage=0,wait=0,last=-1,baseline=0;double start=UnityEditor.EditorApplication.timeSinceStartup;var samples=new System.Collections.Generic.List<int>();UnityEditor.EditorApplication.CallbackFunction tick=null;
System.Action finish=()=>{UnityEditor.EditorApplication.update-=tick;UnityEngine.Time.timeScale=1f;UnityEditor.SceneManagement.EditorSceneManager.playModeStartScene=null;UnityEditor.EditorApplication.isPlaying=false;};
tick=()=>{try{if(!UnityEditor.EditorApplication.isPlaying)return;UnityEngine.Application.runInBackground=true;if(UnityEditor.EditorApplication.timeSinceStartup-start>80)throw new System.Exception("timeout");if(last==UnityEngine.Time.frameCount)return;last=UnityEngine.Time.frameCount;
